224: func parseEvents(raw []byte) (text string, tokens Tokens, cost float64, sessionID string, toolCalls, eventCount int) {
225: 	scanner := bufio.NewScanner(bytes.NewReader(raw))
226: 	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
227: 	var builder strings.Builder
228: 	for scanner.Scan() {
229: 		line := bytes.TrimSpace(scanner.Bytes())
230: 		if len(line) == 0 {
231: 			continue
232: 		}
233: 		var item event
234: 		if err := json.Unmarshal(line, &item); err != nil {
235: 			continue
236: 		}
237: 		eventCount++
238: 		if item.SessionID != "" {
239: 			sessionID = item.SessionID
240: 		}
241: 		var part map[string]json.RawMessage
242: 		if err := json.Unmarshal(item.Part, &part); err != nil {
243: 			continue
244: 		}
245: 		if typeRaw, ok := part["type"]; ok {
246: 			var partType string
247: 			_ = json.Unmarshal(typeRaw, &partType)
248: 			if strings.HasPrefix(partType, "tool") {
249: 				toolCalls++
250: 			}
251: 		}
252: 		if item.Type == "text" {
253: 			if textRaw, ok := part["text"]; ok {
254: 				var chunk string
255: 				if json.Unmarshal(textRaw, &chunk) == nil {
256: 					builder.WriteString(chunk)
257: 				}
258: 			}
259: 		}
260: 		if item.Type == "step_finish" {
261: 			var finish finishPart
262: 			if json.Unmarshal(item.Part, &finish) == nil {
263: 				cost = finish.Cost
264: 				tokens.Input = finish.Tokens.Input
265: 				tokens.Output = finish.Tokens.Output
266: 				tokens.Reasoning = finish.Tokens.Reasoning
267: 				tokens.CacheRead = finish.Tokens.Cache.Read
268: 				tokens.CacheWrite = finish.Tokens.Cache.Write
269: 			}
270: 		}
271: 	}
272: 	return builder.String(), tokens, cost, sessionID, toolCalls, eventCount
273: }
