368: // prepareWorkspace creates an isolated directory and writes the task baseline into it.
369: func prepareWorkspace(root, id string, task Task) (string, error) {
370: 	dir := filepath.Join(root, id)
371: 	if err := os.MkdirAll(dir, 0o755); err != nil {
372: 		return "", err
373: 	}
374: 	names := make([]string, 0, len(task.Files))
375: 	for name := range task.Files {
