func TestAdd(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "positive", a: 2, b: 3, want: 5},
		{name: "negative", a: -2, b: 3, want: 1},
		{name: "zero", a: 0, b: 0, want: 0},
	}

